def show_pi_ai_source():
    """Best-effort: locate pi-ai's openai-completions converter and print the
    line(s) around 'thinkingSignature' so the reasoning_content decision is
    source-confirmed. Tries several candidate node_modules roots; a nested copy
    under pi-coding-agent wins over a sibling. Falls back to a text grep if the
    exact path isn't present. Purely diagnostic (stdout only)."""
    import glob
    fnm_base = pathlib.Path("/home/josiah/.local/share/fnm/node-versions")
    roots = []
    # (a) any fnm version's @earendil-works tree
    if fnm_base.exists():
        for vdir in sorted(fnm_base.glob("*")):
            root = vdir / "installation" / "lib" / "node_modules" / "@earendil-works"
            if root.is_dir():
                roots.append(root)
    # (b) explicit known install
    roots.append(pathlib.Path(
        "/home/josiah/.local/share/fnm/node-versions/v22.20.0/installation/lib/node_modules/@earendil-works"))
    # (c) the repo's own node_modules, if the orchestrator ever puts one there
    roots.append(ROOT / "node_modules" / "@earendil-works")
    # de-duplicate, prefer the deepest (nested) match by preferring later/appending order is fine
    roots = list(dict.fromkeys(roots))
    hits = []
    for root in roots:
        if not root.exists():
            continue
        hits += glob.glob(str(root / "**" / "providers" / "openai-completions.js"), recursive=True)
    hits = list(dict.fromkeys(hits))
    print("pi-ai openai-completions.js candidates:", hits)
    if hits:
        for h in hits:
            lines = pathlib.Path(h).read_text(encoding="utf-8").splitlines()
            for i, l in enumerate(lines):
                if "thinkingSignature" in l:
                    print(f"--- {h}:{i + 1}")
                    print("\n".join(lines[max(0, i - 6): i + 8]))
        return
    # (d) fallback: grep the @earendil-works trees for the signature
    for root in roots:
        if not root.exists():
            continue
        for js in glob.glob(str(root / "**" / "*.js"), recursive=True):
            try:
                txt = pathlib.Path(js).read_text(encoding="utf-8")
            except OSError:
                continue
            for i, l in enumerate(txt.splitlines()):
                if "thinkingSignature" in l:
                    print(f"--- {js}:{i + 1}")
                    print("\n".join(l.splitlines()[max(0, i - 6): i + 8]))
    print("note: converter not located; reasoning_content decision still rests on the data"
          " (0.833 with vs 0.457 without) and event_samples.json thinkingSignature="
